import os
import requests
from zipfile import ZipFile, BadZipFile

def task_func(url, download_path="mnt/data/downloads/"):
    try:
        response = requests.get(url, stream=True)
        if response.status_code != 200:
            return "Error: Unable to download the file from the provided URL."

        content_type = response.headers.get('Content-Type', '')
        if 'application/zip' not in content_type:
            return "Error: The URL does not point to a ZIP file."

        os.makedirs(download_path, exist_ok=True)
        zip_file_path = os.path.join(download_path, "temp.zip")

        with open(zip_file_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        try:
            with ZipFile(zip_file_path, 'r') as zip_ref:
                zip_ref.extractall(download_path)
        except BadZipFile:
            return "Error: The downloaded file is not a valid ZIP file."
        finally:
            if os.path.exists(zip_file_path):
                os.remove(zip_file_path)

        return download_path
    except requests.RequestException:
        return "Error: Unable to download the file from the provided URL."
    except Exception as e:
        return f"Error: {str(e)}"

import requests
from pathlib import Path
import zipfile

DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(exist_ok=True)
    ZIP_DIR.mkdir(exist_ok=True)

    file_path = DOWNLOAD_DIR / filename

    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
        with open(file_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except Exception:
        return ("Error: Network-related issue", [])

    try:
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            file_list = zip_ref.namelist()
        return ("Success", file_list)
    except Exception:
        return ("Error: File-related issue", [])

import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO

def task_func(url, table_id):
    response = requests.get(url, verify=False)
    response.raise_for_status()

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', {'id': table_id})

    if table is None:
        raise ValueError("Table with the specified ID not found.")

    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()

    html_str = str(table)
    df_list = pd.read_html(StringIO(html_str))

    if not df_list:
        return pd.DataFrame()

    return df_list[0]

