import pandas as pd
import requests
from io import StringIO

def task_func(csv_url, sort_by_column="title"):
    response = requests.get(csv_url)
    if response.status_code != 200:
        raise Exception(f"Failed to fetch data, status code: {response.status_code}")

    data = StringIO(response.text)
    df = pd.read_csv(data)

    if sort_by_column not in df.columns:
        raise ValueError(f"Column '{sort_by_column}' not found in CSV data.")

    return df.sort_values(by=sort_by_column)

import ipaddress
import requests

def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError:
        raise ValueError("Invalid IP range provided.")

    active_ips = []
    for ip in network:
        ip_str = str(ip)
        try:
            response = requests.get(f"http://{ip_str}", timeout=timeout)
            if response.status_code == 200:
                active_ips.append(ip_str)
        except requests.RequestException:
            continue

    return active_ips

