from flask import Flask
from flask_restful import Resource, Api
import requests

def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalData(Resource):
        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
                return response.json()
            except requests.RequestException:
                return {"error": "Failed to fetch data from external API"}, 502

    api.add_resource(ExternalData, '/api/data')

    return app

import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    response = requests.get(f"{URL}{username}")
    response.raise_for_status()
    data = response.json()

    def normalize_to_ascii(obj):
        if isinstance(obj, str):
            return unicodedata.normalize('NFKD', obj).encode('ascii', 'ignore').decode('ascii')
        elif isinstance(obj, dict):
            return {k: normalize_to_ascii(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [normalize_to_ascii(i) for i in obj]
        return obj

    return normalize_to_ascii(data)
